// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 initialMinSum, uint256 newMinSum) public {
        // Set the legitimate initial minimum sum before initialization.
        c.SetMinSum(initialMinSum);

        // Freeze the configuration.
        c.Initialized();

        // A post-initialization attempt to change MinSum must be a no-op
        // in the reference contract.
        c.SetMinSum(newMinSum);

        // General rule: after initialization, MinSum keeps its configured value.
        assertEq(c.MinSum(), initialMinSum);
    }
}

