pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 amount, address actor) public {
        vm.assume(actor != address(0));
        amount = bound(amount, 1, 1 ether);

        // configure LogFile (fuzzer-independent setup) and fund the actor
        c.SetLogFile(address(new LogFile()));
        vm.deal(actor, amount);

        // drive c through Put (fallback -> Put(0)) so Log.AddMessage is invoked
        vm.prank(actor);
        (bool okPut, ) = address(c).call{value: amount}("");
        assertTrue(okPut, "Put should succeed");

        // general rule: a logged deposit appears in the LogFile History
        bool logged = false;
        try c.History(0) returns (
            address sender,
            string memory,
            uint256 val,
            uint256
        ) {
            logged = (sender == actor && val == amount);
        } catch {
            logged = false;
        }
        assertTrue(logged);
    }
}

contract LogFile {
    struct Message {
        address Sender;
        string Data;
        uint256 Val;
        uint256 Time;
    }

    Message[] public History;
    Message LastMsg;

    function AddMessage(address _adr, uint256 _val, string memory _data) public {
        LastMsg.Sender = _adr;
        LastMsg.Time = block.timestamp;
        LastMsg.Val = _val;
        LastMsg.Data = _data;
        History.push(LastMsg);
    }
}

