pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C, LogFile} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public {
        c = new C();
    }

    function testFuzz_property(uint256 amount, address actor) public {
        vm.assume(actor != address(0));
        amount = bound(amount, 1, 1 ether);

        LogFile log = new LogFile();
        c.SetLogFile(address(log));
        c.Initialized();

        vm.deal(actor, amount);
        vm.prank(actor);
        c.Put{value: amount}(0);

        assertTrue(log.History_length() >= 1, "Put must record a message in the configured LogFile");
    }
}

