pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address actor, address logAddr) public {
        vm.assume(actor != address(0));
        vm.prank(actor);
        bool ok = true;
        try c.SetLogFile(logAddr) {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(ok && c.Log() == logAddr);
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function test(uint _val) public {
        // _val is never used for MinSum anywhere else; ensure it is distinguishable from 0
        require(_val != 0);
        bool failedBefore = false;
        // Before initialization, SetMinSum must succeed on P.
        c.SetMinSum(_val);
        uint beforeInit = c.MinSum();
        c.Initialized();
        // After initialization, further SetMinSum calls revert on P (and on M).
        (bool ok,) = address(c).call(abi.encodeWithSelector(C.SetMinSum.selector, _val + 1));
        failedBefore = !ok;
        assert(beforeInit == _val && failedBefore);
    }

    receive() external payable {}
    fallback() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function runTest(uint v1, uint v2) public {
        require(v2 != v1);
        c.SetMinSum(v1);
        c.SetMinSum(v2);
        assert(c.MinSum() == v2);
    }

    receive() external payable {}
    fallback() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function test(uint _val) public {
        (bool logOk, ) = address(c).call(abi.encodeWithSignature("SetLogFile(uint256)", uint256(uint160(address(this)))));
        (bool minOk, ) = address(c).call(abi.encodeWithSignature("SetMinSum(uint256)", _val));
        assert(logOk && minOk && c.MinSum() == _val);
    }

    receive() external payable {}
    fallback() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint _am, uint _val) public payable {
        require(true);
        bool reverted;
        try c.Collect(_am) { reverted = false; } catch { reverted = true; }   // boundary
        bool setOk;
        try c.SetMinSum(_val) { setOk = true; } catch { setOk = true; }
        assert(!reverted && setOk && c.MinSum() == _val);
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint _am, uint _val) public payable {
        require(true);
        bool reverted1;
        try c.Collect(_am) { reverted1 = false; } catch { reverted1 = true; }
        require(!reverted1);
        bool reverted2;
        try c.SetMinSum(_val) { reverted2 = false; } catch { reverted2 = true; }
