}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint amount) public payable {
        require(address(this).balance >= amount);
        require(c.MinSum() == 0);
        require(amount > 0);
        c.Put{value: amount}(0);
        bool r1; try c.Collect(amount) { r1 = true; } catch { r1 = false; }
        bool r2; try c.Collect(amount) { r2 = true; } catch { r2 = false; }
        assert(r1 && r2);
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint lockTime, uint amount, address logAddr) public payable {
        require(true);
        if (amount > 0) {
            require(address(this).balance >= amount);
            c.Put{value: amount}(lockTime);
        }
        bool collectReverted;
        try c.Collect(amount) { collectReverted = false; } catch { collectReverted = true; }
        require(!collectReverted);
        bool setLogReverted;
        try c.SetLogFile(logAddr) { setLogReverted = false; } catch { setLogReverted = true; }
        assert(!setLogReverted);
    }
    receive() external payable {}
}
